function union(a, b) {
  const result = [];
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    let next;
    if (j >= b.length || (i < a.length && a[i] <= b[j])) next = a[i++];
    else next = b[j++];
    if (result.length === 0 || result[result.length - 1] !== next) {
      result.push(next);            // skip a value equal to the last one
    }
  }
  return result;
}

def union(a, b):
    result = []
    i = j = 0
    while i < len(a) or j < len(b):
        if j >= len(b) or (i < len(a) and a[i] <= b[j]):
            nxt = a[i]
            i += 1
        else:
            nxt = b[j]
            j += 1
        if not result or result[-1] != nxt:
            result.append(nxt)        # skip a value equal to the last one
    return result

class Solution {
    public List<Integer> union(int[] a, int[] b) {
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length || j < b.length) {
            int next;
            if (j >= b.length || (i < a.length && a[i] <= b[j])) next = a[i++];
            else next = b[j++];
            if (result.isEmpty() || result.get(result.size() - 1) != next) {
                result.add(next);       // skip a value equal to the last one
            }
        }
        return result;
    }
}

class Solution {
public:
    vector<int> unionOf(vector<int>& a, vector<int>& b) {
        vector<int> result;
        size_t i = 0, j = 0;
        while (i < a.size() || j < b.size()) {
            int next;
            if (j >= b.size() || (i < a.size() && a[i] <= b[j])) next = a[i++];
            else next = b[j++];
            if (result.empty() || result.back() != next) {
                result.push_back(next);   // skip a value equal to the last one
            }
        }
        return result;
    }
};
